function go(id){view=id;render()}
function squadPage(){setLineup();const starters=state.squad.filter(p=>p.starter).sort((a,b)=>roles.indexOf(a.pos)-roles.indexOf(b.pos));const reserves=state.squad.filter(p=>!p.starter).sort((a,b)=>roles.indexOf(a.pos)-roles.indexOf(b.pos));return `${heading('La tua squadra','Rosa & tattica','Disponibilità, forma e scelte di formazione. Modifiche sempre possibili.') }<div class="grid main-grid"><section class="card section"><div class="section-title"><h2>Impostazioni tattiche</h2><span class="tag">${avgLevel()} OVR titolari</span></div><div style="display:flex;gap:14px;flex-wrap:wrap;margin-bottom:17px"><label class="muted">Modulo<br><select class="select" onchange="setFormation(this.value)">${Object.keys(formations).map(x=>`<option ${state.formation===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="muted">Stile di gioco<br><select class="select" onchange="state.tactic=this.value;save();say('Atteggiamento aggiornato')">${['Equilibrato','Pressing alto','Contropiede','Possesso palla','Difesa bassa','Tutto per tutto'].map(x=>`<option ${state.tactic===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="pitch">${['ATT','AD','AS','CC','MED','DC','TD','TS','POR'].map(pos=>{const players=starters.filter(p=>p.pos===pos);return players.length?`<div class="pitch-line">${players.map(p=>`<div class="shirt">${p.name.split(' ')[1]}<small>${p.pos} · ${p.overall}</small></div>`).join('')}</div>`:''}).join('')}</div><div class="section-title" style="margin-top:22px"><h2>Titolari · ${starters.length}/11</h2><small>La selezione automatica schiera i più forti</small></div>${playerList(starters)}<div class="section-title" style="margin-top:22px"><h2>Panchina & riserve</h2><small>${reserves.length} giocatori</small></div>${playerList(reserves)}</section><section class="grid" style="align-content:start"><div class="card section"><div class="section-title"><h2>Disponibilità</h2></div><div class="fixture"><span>Infortunati</span><b class="${state.squad.some(p=>p.injury)?'red':'lime'}">${state.squad.filter(p=>p.injury).length}</b></div><div class="fixture"><span>Squalificati</span><b class="${state.squad.some(p=>p.bans)?'red':'lime'}">${state.squad.filter(p=>p.bans).length}</b></div><div class="fixture"><span>Forma media</span><b>${Math.round(state.squad.reduce((a,p)=>a+p.stamina,0)/state.squad.length)}%</b></div><button class="btn wide" style="margin-top:12px" onclick="autoLineup()">↻ Miglior formazione</button></div><div class="card section"><div class="section-title"><h2>Regole squadra</h2></div><p class="muted" style="font-size:13px">La stanchezza diminuisce dopo ogni gara. Infortuni e squalifiche si risolvono con il passare delle giornate. Puoi cambiare assetto prima e durante ogni partita.</p></div></section></div>`}
function playerList(players){return `<div class="player-row head"><span>Giocatore</span><span>Ruolo</span><span>OVR</span><span>Età</span><span>Forma</span><span>Stato</span></div>${players.map(p=>`<div class="player-row"><div><div class="player-name">${esc(p.name)}</div><div class="player-meta">Valore ${money(p.value)} · ${p.goals} gol</div></div><span>${p.pos}</span><b>${p.overall}</b><span>${p.age}</span><span style="color:${p.stamina<45?'var(--red)':'var(--lime)'}">${p.stamina}%</span><span>${p.injury?`<span class="status red">Infortunato ${p.injury}g</span>`:p.bans?`<span class="status red">Squalifica ${p.bans}g</span>`:`<button class="btn small" onclick="toggleStarter('${p.id}')">${p.starter?'Titolare':'Schiera'}</button>`}</span></div>`).join('')}`}
function setFormation(v){state.formation=v;setLineup();save();render()}function autoLineup(){setLineup();save();render();say('Miglior formazione schierata')}function toggleStarter(id){let p=state.squad.find(x=>x.id===id);if(!p||p.injury||p.bans)return;p.starter=!p.starter;if(state.squad.filter(x=>x.starter).length>11){p.starter=false;say('Massimo 11 titolari');return}save();render()}
function marketPage(){const offers=state.squad.filter(p=>!p.starter&&p.overall>55);return `${heading('Area tecnica','Calciomercato','Acquista, cedi e rinnova la rosa.',`<span class="tag">${money(state.budget)} disponibili</span>`)}<div class="grid main-grid"><section class="card section"><div class="section-title"><h2>Mercato attivo</h2><span class="status">${state.week<4?'Finestra estiva':state.week>=17&&state.week<=24?'Finestra invernale':'Scouting continuo'}</span></div><div class="notice">Ogni sessione assegna <b>500 crediti</b> di budget alla tua squadra. Le cessioni aumentano i fondi; ingaggi e trasferimenti sono inclusi nel prezzo.</div><div class="tabs" style="margin-top:18px"><button class="tab active" id="tab-buy" onclick="showMarketTab('buy')">Obiettivi scouting</button><button class="tab" id="tab-sell" onclick="showMarketTab('sell')">Lista cessioni</button></div><div id="market-content">${marketBuy()}</div></section><section class="card section"><div class="section-title"><h2>Movimenti nel mondo</h2><span class="tag">LIVE</span></div>${state.transfers.slice(0,6).map(t=>`<div class="fixture"><div><div class="opponent">${esc(t.player)}</div><small>${esc(t.from)} → ${esc(t.to)}</small></div><b class="kick">${money(t.fee)}</b></div>`).join('')||'<p class="muted">I rumors di mercato compariranno qui.</p>'}<button class="btn wide" style="margin-top:14px" onclick="worldTransfer()">Simula notizie di mercato</button></section></div>`}
function marketBuy(){const list=makeMarket();return `<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">${list.map(p=>`<article class="card" style="padding:14px;background:#ffffff04"><div class="eyebrow">${p.pos} · ${p.age} anni · OVR ${p.overall}</div><h3 style="font-size:15px;margin:6px 0">${esc(p.name)}</h3><div style="display:flex;justify-content:space-between;align-items:center"><span class="muted">${money(p.value)}</span><button class="btn small primary" onclick="buyPlayer('${p.id}')">Acquista</button></div></article>`).join('')}</div><p class="muted" style="font-size:12px;margin-top:12px">Profili di fascia bassa: 20–80 crediti. I top player costano migliaia di crediti.</p>`}
function makeMarket(){if(!state.marketPool){state.marketPool=Array.from({length:8},(_,i)=>makePlayer(i,49+Math.floor(Math.random()*17),19+Math.floor(Math.random()*12)));state.marketPool.push(makePlayer(9,86,26));}return state.marketPool}
function marketSell(){return `<div class="player-row head"><span>Giocatore</span><span>Ruolo</span><span>OVR</span><span>Età</span><span>Prezzo</span><span></span></div>${state.squad.filter(p=>!p.starter).map(p=>`<div class="player-row"><b>${esc(p.name)}</b><span>${p.pos}</span><b>${p.overall}</b><span>${p.age}</span><span>${money(p.value)}</span><button class="btn small danger" onclick="sellPlayer('${p.id}')">Cedi</button></div>`).join('')}`}
function showMarketTab(tab){document.getElementById('tab-buy')?.classList.toggle('active',tab==='buy');document.getElementById('tab-sell')?.classList.toggle('active',tab==='sell');document.getElementById('market-content').innerHTML=tab==='buy'?marketBuy():marketSell()}
function buyPlayer(id){let p=makeMarket().find(p=>p.id===id);if(!p)return;if(state.budget<p.value){say('Budget insufficiente');return}if(state.squad.length>=30){say('Rosa al completo (max 30)');return}state.budget-=p.value;state.squad.push({...p,stamina:100});state.marketPool=state.marketPool.filter(x=>x.id!==id);save();render();say(`${p.name} è un nuovo giocatore!`)}
function sellPlayer(id){const p=state.squad.find(p=>p.id===id);if(!p)return;state.squad=state.squad.filter(x=>x.id!==id);state.budget+=p.value;save();render();say(`Cessione completata: +${money(p.value)}`)}
function worldTransfer(){const names=['Real Madrigal','North London City','Bayernheim','Paris Royale','Milano Rossonera','Barcellona del Mar'];const a=names[Math.floor(Math.random()*names.length)],b=names.filter(x=>x!==a)[Math.floor(Math.random()*5)],p=makePlayer(10,78+Math.floor(Math.random()*9),22+Math.floor(Math.random()*9));const fee=1800+Math.floor(Math.random()*6000);state.transfers.unshift({player:p.name,from:a,to:b,fee});addNews(`${b} mette a segno il colpo ${p.name}: affare da ${fee.toLocaleString('it-IT')} crediti.`, '💸','market');save();render();say('Ultima notizia di mercato aggiornata')}
function worldPage(){return `${heading('Social & notizie','Mondo Calcio','Il feed del pallone: campo, mercato e voci di spogliatoio.',`<button class="btn" onclick="generateWorldNews()">↻ Aggiorna feed</button>`)}<div class="grid main-grid"><section class="card section"><div class="section-title"><h2>Il feed</h2><span class="status">${state.day} · aggiornato</span></div>${state.news.length?state.news.map(feedItem).join(''):'<div class="empty">Nessuna notizia al momento. Il mondo del calcio si sta svegliando…</div>'}</section><section class="grid" style="align-content:start"><div class="card section"><div class="section-title"><h2>La tua eco social</h2><span class="tag">@RTGM</span></div>${socialPosts().map(n=>`<div class="feed-item"><div class="feed-icon">${n.icon}</div><div><p><b>${n.user}</b> <span class="muted">${n.handle}</span></p><p style="margin-top:5px">${n.text}</p><small>♡ ${n.likes} · ${n.time}</small></div></div>`).join('')}</div><div class="card section"><div class="section-title"><h2>Premi stagionali</h2><span class="status">Stagione ${state.season}</span></div><div class="fixture"><div><b>Pallone d’Oro</b><small style="display:block">${state.week>30?'Assegnazione a fine stagione':'In palio a giugno'}</small></div><span>🏅</span></div><div class="fixture"><div><b>Miglior giovane</b><small style="display:block">Talent scout al lavoro</small></div><span>🌟</span></div><div class="fixture"><div><b>Allenatore dell’anno</b><small style="display:block">${state.rep>=40?'Sei tra i candidati':'La reputazione cresce'}</small></div><span>🧠</span></div></div></section></div>`}
function socialPosts(){let user=state.clubName.split(' ')[0];return[{icon:'💚',user:'Curva '+user,handle:'@ultras_'+user.toLowerCase(),text:myTable()<=8?'Mister ha dato un’identità alla squadra. Avanti così!':'Serve una scossa, questa classifica non ci rappresenta.',likes:320+state.week*7,time:'12 min'},{icon:'🎙️',user:'Mister avversario',handle:'@coach_voice',text:`Contro ${state.clubName} ci aspetta una partita vera. Hanno qualità e fame.`,likes:87,time:'1 h'},{icon:'👀',user:'Spogliatoio anonimo',handle:'@insidefootball',text:'Si dice che il gruppo sia compatto e pronto a seguire il nuovo progetto.',likes:156,time:'3 h'}]}
function generateWorldNews(){const headlines=['Clamoroso in coppa: la favorita saluta ai quarti dopo una rimonta incredibile.','La capolista cade in trasferta: campionato riaperto a sorpresa!','Voci di mercato: un giovane talento è seguito da mezza Europa.','Serata europea da ricordare: tripletta e record per il bomber della stagione.','Un derby acceso finisce in parità: tifosi divisi sui social.'];addNews(headlines[Math.floor(Math.random()*headlines.length)],['🌍','⚡','🗞️','🏆'][Math.floor(Math.random()*4)]);save();render();say('Feed aggiornato')}

