 function render(){const root=document.getElementById('app');if(!state?.gameStarted){root.innerHTML=header()+intro();return}let content=view==='home'?home():view==='squad'?squadPage():view==='market'?marketPage():view==='world'?worldPage():careerPage();root.innerHTML=layout(content);}
 function intro(){return `<main style="max-width:1080px;margin:0 auto;padding:44px 20px 60px"><div class="eyebrow">La tua panchina ti aspetta</div><h1 style="font-size:clamp(36px,6vw,64px);letter-spacing:-.06em;line-height:1.02;max-width:700px;margin:12px 0">Dal fango dei campi di provincia <span class="lime">alla gloria.</span></h1><p style="color:var(--muted);font-size:17px;max-width:670px;line-height:1.65">Costruisci una carriera, conquista trofei e scrivi la tua storia. Ogni scelta è tua: il tempo avanza solo quando lo decidi tu.</p><div class="section-title" style="margin:34px 0 14px"><h2>Scegli il tuo primo incarico</h2><small>5 club · Stagione 1</small></div><div class="team-grid">${clubs.map((c,i)=>`<article class="card choice"><div><div class="eyebrow">${c.league} · ${c.city}</div><h3>${c.name}</h3><p>${c.style}</p><div class="choice-details"><span>Rosa <b>${c.level}</b></span><span>Budget <b>500 cr</b></span><span>Prestigio <b>${c.prestige}</b></span></div><div style="margin-top:9px"><span class="tag">Obiettivo: ${c.target}</span></div></div><button class="btn primary" onclick="initGame(${i})">Scegli club ↗</button></article>`).join('')}</div><p style="color:#778274;font-size:12px;margin-top:18px">Club e atleti sono fittizi, creati per il gioco. Partite e mercato sono simulati.</p></main>`}
 function home(){const rank=myTable(),next=nextFixture(),opp=opponentOf(next);const standings=sortedTable();const matchBtn=state.week<state.fixtures.length?`<button class="btn primary" onclick="openMatchSetup()">Vai alla partita&nbsp; ↗</button>`:`<button class="btn primary" onclick="endSeason()">Concludi stagione ↗</button>`;return `${heading('Stagione '+state.season,'Benvenuto, Mister.',`${state.day} · ${state.league}`,matchBtn)}<div class="grid stats"><div class="card stat"><label>Posizione in campionato</label><strong>${rank}<span style="font-size:14px;color:var(--muted)"> / ${state.table.length}</span></strong><small>${rank<=3?'Zona promozione':rank>state.table.length-4?'Zona retrocessione':'Classifica generale'}</small></div><div class="card stat"><label>Prossimo avversario</label><strong style="font-size:19px;margin-top:10px">${opp?esc(opp):'Fine stagione'}</strong><small>${next?`Giornata ${state.week+1} · ${next.home===state.clubName?'In casa':'In trasferta'}`:'Pronto per la nuova stagione'}</small></div><div class="card stat"><label>Crediti disponibili</label><strong class="lime">${money(state.budget)}</strong><small>Mercato estivo/invernale</small></div><div class="card stat"><label>Obiettivo dirigenza</label><strong style="font-size:18px;margin-top:10px">${esc(state.target)}</strong><small class="${objectiveStatus().includes('Sotto')||objectiveStatus().includes('rischio')?'red':'lime'}">${objectiveStatus()}</small></div></div><div class="grid main-grid"><section class="card section"><div class="section-title"><h2>Classifica</h2><small>${state.league}</small></div><table class="table"><thead><tr><th>#</th><th style="text-align:left">Club</th><th>PG</th><th>DR</th><th>PT</th></tr></thead><tbody>${standings.slice(0,5).map((t,i)=>tableRow(t,i)).join('')}${rank>5&&rank<=state.table.length-3?`<tr class="mine"><td>…</td><td style="text-align:left">${esc(state.clubName)}</td><td>${state.week}</td><td>${myRow().gf-myRow().ga}</td><td>${myRow().pts}</td></tr>`:''}${standings.slice(-3).map((t,i)=>tableRow(t,standings.length-3+i)).join('')}</tbody></table><div class="actions" style="margin-top:14px"><button class="btn small" onclick="go('squad')">Gestisci la rosa</button><button class="btn small" onclick="go('world')">Apri Mondo Calcio</button></div></section><div class="grid" style="align-content:start"><section class="card section"><div class="section-title"><h2>Voce dalla clubhouse</h2><span class="tag">LIVE</span></div><div class="target"><strong>${esc(state.target)}</strong><span class="muted">La dirigenza valuta il tuo lavoro: <b class="${objectiveStatus().includes('Sotto')?'red':'lime'}">${objectiveStatus()}</b></span><div class="progress"><i style="width:${rank<=8?78:35}%"></i></div></div><div style="margin-top:16px" class="fixture"><div class="club"><div class="crest">${state.clubName.slice(0,2).toUpperCase()}</div><div><div class="opponent">${esc(state.clubName)}</div><small>Rosa · ${state.squad.length} giocatori</small></div></div><strong class="kick">${avgLevel()} OVR</strong></div><div class="fixture"><div class="club"><div class="crest">🏆</div><div><div class="opponent">Palmarès</div><small>Trofei in carriera</small></div></div><strong class="kick">${state.trophies}</strong></div></section><section class="card section"><div class="section-title"><h2>Ultime dal mondo</h2><button class="btn small" onclick="go('world')">Tutte →</button></div>${state.news.slice(0,2).map(feedItem).join('')||'<p class="muted">Le notizie arriveranno presto.</p>'}</section></div></div>`}
 function myRow(){return state.table.find(t=>t.name===state.clubName)}function tableRow(t,i){return `<tr class="${t.name===state.clubName?'mine':''}"><td class="rank">${i+1}</td><td style="text-align:left">${esc(t.name)}</td><td>${t.w+t.d+t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td></tr>`}function avgLevel(){return Math.round(state.squad.filter(p=>p.starter).reduce((a,p)=>a+p.overall,0)/Math.max(1,state.squad.filter(p=>p.starter).length))}function feedItem(n){return `<div class="feed-item"><div class="feed-icon">${n.icon}</div><div><p>${esc(n.text)}</p><small>${n.day||state.day} · ${n.kind==='social'?'Social':n.kind==='market'?'Mercato':'Mondo Calcio'}</small></div></div>`}
-</script>
-</body></html>
