section-title"><h2>Stagioni</h2></div>${state.history.slice(-5).reverse().map(x=>`<div class="fixture"><span>Stagione ${x.season} · ${esc(x.club)}</span><b class="${x.result==='success'?'lime':'muted'}">${x.rank}° posto ${x.trophy?'· 🏆':''}</b></div>`).join('')||'<p class="muted">La tua storia comincia oggi.</p>'}</section></div>`}
function careerOffers(){let options=[{name:'FC Monteluce',city:'Monteluce',league:'Serie B',level:66,prestige:36,target:'Lottare per la promozione',goal:'promotion'},{name:'Eastborough Rovers',city:'Eastborough',league:'League One',level:68,prestige:40,target:'Metà classifica',goal:'mid'},{name:'SC Rheinstadt',city:'Rheinstadt',league:'2. Bundesliga',level:70,prestige:45,target:'Salvezza',goal:'safe'},{name:'Città di Lario',city:'Lario',league:'Serie B',level:73,prestige:52,target:'Playoff promozione',goal:'playoffs'}];return options.filter(o=>state.rep>=o.prestige-20&&state.rep+state.trophies*8>=o.prestige-12).slice(0,3)}
function acceptOffer(i){const o=careerOffers()[i];if(!o)return;let old=state.clubName;state.clubName=o.name;state.league=o.league;state.level=o.level;state.budget=500;state.target=o.target;state.goal=o.goal;state.prestige=o.prestige;state.contract=2;state.table[0].name=o.name;state.table[0].level=o.level;state.squad=Array.from({length:22},(_,j)=>makePlayer(j,o.level));setLineup();makeFixtures();addNews(`Nuova avventura: ${state.clubName} presenta il suo nuovo allenatore, in arrivo da ${old}.`,'🖊️');state.week=0;state.day='Lun 04 Ago';save();view='home';render();say('Nuovo incarico accettato!')}
function openMatchSetup(type='league'){if(!nextFixture()&&type==='league'){say('Stagione completata');return}const match=nextFixture();const opp=opponentOf(match);const isCup=type==='cup';if(isCup&&state.cupRound>=5){say('Coppa nazionale già conclusa');return}if(isCup&&state.cupRound===0){state.cupRound=1}const target=opp||state.table.filter(t=>t.name!==state.clubName).sort((a,b)=>a.level-b.level)[0]?.name;document.getElementById('modal-root').innerHTML=`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="eyebrow">${isCup?'Coppa nazionale':'Giornata '+(state.week+1)}</div><h2>Preparati alla partita</h2><p>${esc(state.clubName)} ${match?.home===state.clubName?'vs':'@'} <b>${esc(target||'Avversario')}</b> · ${state.tactic} · ${avgLevel()} OVR</p><div class="section-title" style="margin-top:20px"><h2>Scegli la simulazione</h2></div><div class="grid" style="grid-template-columns:repeat(3,1fr)"><button class="card" style="padding:14px;text-align:left;background:#ffffff06" onclick="startMatch('fast','${isCup?'cup':'league'}')"><b>⚡ Veloce</b><p class="muted" style="font-size:12px">Risultato, marcatori ed eventi.</p></button><button class="card" style="padding:14px;text-align:left;background:#ffffff06" onclick="startMatch('normal','${isCup?'cup':'league'}')"><b>📋 Normale</b><p class="muted" style="font-size:12px">Cronaca divisa in due tempi.</p></button><button class="card" style="padding:14px;text-align:left;background:#ffffff06" onclick="startMatch('detailed','${isCup?'cup':'league'}')"><b>🎮 Dettagliata</b><p class="muted" style="font-size:12px">Fasce da 10', pause e cambi tattici.</p></button></div><div class="actions" style="margin-top:17px"><button class="btn" onclick="go('squad');closeModal()">Gestisci formazione</button><button class="btn" onclick="closeModal()">Annulla</button></div></div></div>`}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function startMatch(mode,type){const fixture=nextFixture();const opp=type==='league'?opponentOf(fixture):(state.table.filter(t=>t.name!==state.clubName).sort((a,b)=>b.level-a.level)[(state.cupRound+state.season)%state.table.length-1]?.name||state.table[1].name);const home=type==='cup'?Math.random()<.5:fixture.home===state.clubName;const team=state.table.find(t=>t.name===opp)||{name:opp,level:state.level-2};const strength=avgLevel()+(home?2:0)+(state.tactic==='Pressing alto'?1:0);let goalsHome=poisson(Math.max(.25,1.15+(home?strength-team.level:team.level-strength)*.045));let goalsAway=poisson(Math.max(.2,1.0+(home?team.level-strength:strength-team.level)*.045));const score=home?[goalsHome,goalsAway]:[goalsAway,goalsHome];let events=buildEvents(score[0],score[1],opp,home);state.match={mode,type,opp,home,score,events,minute:0,log:[],substitutions:0};if(mode==='detailed'){renderMatchLive();return}if(mode==='normal'){renderMatchNormal();return}finishMatch();}
function poisson(lambda){let L=Math.exp(-Math.min(lambda,3)),k=0,p=1;do{k++;p*=Math.random()}while(p>L&&k<8);return k-1}
function buildEvents(homeGoals,awayGoals,opp,home){let out=[];for(let i=0;i<homeGoals;i++){let p=pickScorer(true);out.push({min:3+Math.floor(Math.random()*86),text:`GOAL! ${p?.name||'Il centravanti'} insacca per ${home?state.clubName:opp}.`,goal:true,player:p?.id})}for(let i=0;i<awayGoals;i++){let p=pickScorer(false);out.push({min:5+Math.floor(Math.random()*84),text:`Rete di ${p?.name||'l’attaccante'}: ${home?opp:state.clubName} trova il gol.`,goal:true,player:p?.id})}for(let i=0;i<2+Math.floor(Math.random()*3);i++){let min=8+Math.floor(Math.random()*79);out.push({min,text:[`Grande parata del portiere, che salva il risultato.`,`Occasione! Il tiro sfiora il palo.`,`Ammonizione per un intervento in ritardo.`,`La partita si accende: ritmo alto e duelli a centrocampo.`][Math.floor(Math.random()*4)],goal:false})}return out.sort((a,b)=>a.min-b.min)}
function pickScorer(home){let candidates=state.squad.filter(p=>p.starter&&p.pos!=='POR');return candidates[Math.floor(Math.random()*candidates.length)]}
function renderMatchNormal(){const m=state.match;const halftime=m.events.filter(e=>e.min<=45),second=m.events.filter(e=>e.min>45);let c=`<div class="modal-back"><div class="modal" style="width:min(720px,100%)"><div class="eyebrow">CRONACA · ${m.type==='cup'?'Coppa nazionale':'Campionato'}</div><h2>${esc(m.home?state.clubName:m.opp)} vs ${esc(m.home?m.opp:state.clubName)}</h2><div class="section-title"><h2>Primo tempo</h2></div>${halftime.map(eventHtml).join('')||'<p class="muted">Partita bloccata, squadre attente.</p>'}<div class="section-title" style="margin-top:18px"><h2>Secondo tempo</h2></div>${second.map(eventHtml).join('')||'<p class="muted">Poche occasioni nella ripresa.</p>'}<div class="actions" style="justify-content:flex-end;margin-top:15px"><button class="btn primary" onclick="finishMatch()">Mostra risultato finale</button></div></div></div>`;document.getElementById('modal-root').innerHTML=c}
function eventHtml(e){return `<div class="match-event ${e.goal?'goal':''}"><b>${e.min}'</b> &nbsp;${esc(e.text)}</div>`}
function renderMatchLive(){const m=state.match;const events=m.events.filter(e=>e.min<=m.minute);const goalCount=m.events.filter(e=>e.goal&&e.min<=m.minute).length;let oppGoals=Math.max(0,goalCount-state.squad.filter(p=>p.goals>0).length);document.getElementById('modal-root').innerHTML=`<div class="modal-back"><div class="modal" style="width:min(760px,100%)"><div class="eyebrow">DIRETTA · ${m.minute>=90?'TEMPO SCADUTO':`MINUTO ${m.minute}`}</div><div class="scoreboard"><div class="team">${esc(m.home?state.clubName:m.opp)}</div><strong>${scoreLive(0)} – ${scoreLive(1)}</strong><div class="team">${esc(m.home?m.opp:state.clubName)}</div></div><div class="section-title"><h2>La partita</h2><span class="status">${state.formation} · ${state.tactic}</span></div><div style="max-height:210px;overflow:auto">${events.slice(-7).map(eventHtml).join('')||'<p class="muted">Fischio d’inizio. Le squadre prendono le misure…</p>'}</div><div class="actions" style="margin-top:17px"><button class="btn" onclick="matchTactic()">Cambia atteggiamento</button><button class="btn" onclick="substitute()">Sostituzione (${m.substitutions}/5)</button><button class="btn primary" onclick="advanceMatchMinute()">${m.minute>=90?'Termina partita':'Avanza 10\''}</button></div><p class="muted" style="font-size:11px;margin:12px 0 0">Puoi fare modifiche in ogni pausa. Nessun tempo avanza senza un tuo comando.</p></div></div>`}
function scoreLive(side){let count=state.match.events.filter(e=>e.goal&&e.min<=state.match.minute).length;let own=state.match.events.filter(e=>e.goal&&e.min<=state.match.minute&&e.player);const our=count?Math.min(state.match.score[state.match.home?0:1],own.length):0;const theirs=count-our;return side===0?(state.match.home?our:theirs):(state.match.home?theirs:our)}
function advanceMatchMinute(){state.match.minute=Math.min(90,state.match.minute+10);if(state.match.minute>=90){renderMatchLive();return}renderMatchLive()}
function matchTactic(){const opts=['Equilibrato','Pressing alto','Contropiede','Possesso palla','Difesa bassa','Tutto per tutto'];let i=opts.indexOf(state.tactic);state.tactic=opts[(i+1)%opts.length];say('Assetto: '+state.tactic);renderMatchLive()}
function substitute(){const m=state.match;if(m.substitutions>=5){say('Hai esaurito le sostituzioni');return}const out=state.squad.find(p=>p.starter&&p.pos!=='POR'),inn=state.squad.find(p=>!p.starter&&!p.injury&&!p.bans);if(!out||!inn){say('Nessuna sostituzione disponibile');return}out.starter=false;inn.starter=true;m.substitutions++;save();renderMatchLive();say(`${inn.name} per ${out.name}`)}

