function closeModal(){document.getElementById('modal-root').innerHTML=''}
function startMatch(mode,type){const fixture=nextFixture();let opp;if(type==='league')opp=opponentOf(fixture);else opp=state.table.filter(t=>t.name!==state.clubName).sort((a,b)=>b.level-a.level)[(state.cupRound+state.season)%state.table.length-1]?.name||state.table[1].name;const home=type==='cup'?Math.random()<.5:fixture.home===state.clubName;const team=state.table.find(t=>t.name===opp)||{name:opp,level:state.level-2};const strength=avgLevel()+(home?2:0)+(state.tactic==='Pressing alto'?1:0);let goalsHome=poisson(Math.max(.25,1.15+(home?strength-team.level:team.level-strength)*.045));let goalsAway=poisson(Math.max(.2,1.0+(home?team.level-strength:strength-team.level)*.045));const score=home?[goalsHome,goalsAway]:[goalsAway,goalsHome];let events=buildEvents(score[0],score[1],opp,home);state.match={mode,type,opp,home,score,events,minute:0,log:[],substitutions:0};if(mode==='detailed'){renderMatchLive();return}if(mode==='normal'){renderMatchNormal();return}finishMatch()}
function poisson(lambda){let L=Math.exp(-Math.min(lambda,3)),k=0,p=1;do{k++;p*=Math.random()}while(p>L&&k<8);return k-1}
function buildEvents(homeGoals,awayGoals,opp,home){let out=[];for(let i=0;i<homeGoals;i++){let p=pickScorer(true);out.push({min:3+Math.floor(Math.random()*86,text:`GOAL! ${p?.name||'Il centravanti'} insacca per ${home?state.clubName:opp}.`,goal:true,player:p?.id})}for(let i=0;i<awayGoals;i++){let p=pickScorer(false);out.push({min:5+Math.floor(Math.random()*84,text:`Rete di ${p?.name||'l’attaccante'}: ${home?opp:state.clubName} trova il gol.`,goal:true,player:p?.id})}for(let i=0;i<2+Math.floor(Math.random()*3);i++){let min=8+Math.floor(Math.random()*79);out.push({min,text:[`Grande parata del portiere, che salva il risultato.`,`Occasione! Il tiro sfiora il palo.`,`Ammonizione per un intervento in ritardo.`,`La partita si accende: ritmo alto e duelli a centrocampo.`][Math.floor(Math.random()*4)],goal:false})}return out.sort((a,b)=>a.min-b.min)}
function pickScorer(home){let candidates=state.squad.filter(p=>p.starter&&p.pos!=='POR');return candidates[Math.floor(Math.random()*candidates.length)]}
function renderMatchNormal(){const m=state.match;const halftime=m.events.filter(e=>e.min<=45),second=m.events.filter(e=>e.min>45);let c=`<div class="modal-back"><div class="modal" style="width:min(720px,100%)"><div class="eyebrow">CRONACA · ${m.type==='cup'?'Coppa nazionale':'Campionato'}</div><h2>${esc(m.home?state.clubName:m.opp)} vs ${esc(m.home?m.opp:state.clubName)}</h2><div class="section-title"><h2>Primo tempo</h2></div>${halftime.map(eventHtml).join('')||'<p class="muted">Partita bloccata, squadre attente.</p>'}<div class="section-title" style="margin-top:18px"><h2>Secondo tempo</h2></div>${second.map(eventHtml).join('')||'<p class="muted">Poche occasioni nella ripresa.</p>'}<div class="actions" style="justify-content:flex-end;margin-top:15px"><button class="btn primary" onclick="finishMatch()">Mostra risultato finale</button></div></div></div>`;document.getElementById('modal-root').innerHTML=c}
function eventHtml(e){return `<div class="match-event ${e.goal?'goal':''}"><b>${e.min}'</b> &nbsp;${esc(e.text)}</div>`}
function renderMatchLive(){const m=state.match;const events=m.events.filter(e=>e.min<=m.minute);document.getElementById('modal-root').innerHTML=`<div class="modal-back"><div class="modal" style="width:min(760px,100%)"><div class="eyebrow">DIRETTA · ${m.minute>=90?'TEMPO SCADUTO':`MINUTO ${m.minute}`}</div><div class="scoreboard"><div class="team">${esc(m.home?state.clubName:m.opp)}</div><strong>${scoreLive(0)} – ${scoreLive(1)}</strong><div class="team">${esc(m.home?m.opp:state.clubName)}</div></div><div class="section-title"><h2>La partita</h2><span class="status">${state.formation} · ${state.tactic}</span></div><div style="max-height:210px;overflow:auto">${events.slice(-7).map(eventHtml).join('')||'<p class="muted">Fischio d’inizio. Le squadre prendono le misure…</p>'}</div><div class="actions" style="margin-top:17px"><button class="btn" onclick="matchTactic()">Cambia atteggiamento</button><button class="btn" onclick="substitute()">Sostituzione (${m.substitutions}/5)</button><button class="btn primary" onclick="advanceMatchMinute()">${m.minute>=90?'Termina partita':'Avanza 10\''}</button></div><p class="muted" style="font-size:11px;margin:12px 0 0">Puoi fare modifiche in ogni pausa. Nessun tempo avanza senza un tuo comando.</p></div></div>`}
