function finishMatch(){const m=state.match;if(!m)return;if(m.mode==='detailed'&&m.minute<90){m.minute=90;renderMatchLive();return}let userGoals=m.events.filter(e=>e.goal&&e.player).length;let oppGoals=m.score[0]+m.score[1]-userGoals;if(userGoals+oppGoals===0)oppGoals=0;let summary=`${state.clubName} ${userGoals}–${oppGoals} ${m.opp}`;let user=state.table.find(t=>t.name===state.clubName),opp=state.table.find(t=>t.name===m.opp);if(m.type==='league'){recordResult(user,opp,m.home?userGoals:oppGoals,m.home?oppGoals:userGoals);simulateOtherGames();state.week++;advanceDate();}else{if(userGoals===oppGoals){if(Math.random()<.5)userGoals++;else oppGoals++}if(userGoals>oppGoals){state.cupRound++;if(state.cupRound>=5){state.trophies++;state.rep+=10;addNews(`${state.clubName} alza la Coppa nazionale! Trionfo storico per il club.`,`🏆`);}}else state.cupRound=5;summary=`${state.clubName} ${userGoals}–${oppGoals} ${m.opp} · Coppa`;}
 const ourPlayers=m.events.filter(e=>e.goal&&e.player).map(e=>state.squad.find(p=>p.id===e.player)).filter(Boolean);ourPlayers.forEach(p=>p.goals++);handleMatchEvents();const won=userGoals>oppGoals,draw=userGoals===oppGoals;if(m.type==='league'){state.rep+=won?2:draw?1:-1;user.matchForm=won?'V':draw?'N':'P'}addNews(`${summary}${won?' · Vittoria':draw?' · Pareggio':' · Sconfitta'}.`,won?'🎉':'⚽');save();const message=m.mode==='fast'?`<div class="section-title"><h2>Eventi principali</h2></div>${m.events.filter(e=>e.goal).map(eventHtml).join('')||'<p class="muted">Reti inviolate. Difese protagoniste.</p>'}`:'';document.getElementById('modal-root').innerHTML=`<div class="modal-back"><div class="modal"><div class="eyebrow">FISCHIO FINALE · ${m.type==='cup'?'COPPA NAZIONALE':'CAMPIONATO'}</div><div class="scoreboard"><div class="team">${esc(m.home?state.clubName:m.opp)}</div><strong>${m.score[0]} – ${m.score[1]}</strong><div class="team">${esc(m.home?m.opp:state.clubName)}</div></div>${message}<div class="notice" style="margin-top:14px">${won?'Ottimo lavoro, Mister.':draw?'Un punto importante per la classifica.':'La squadra dovrà reagire alla prossima.'} ${state.week%19===0&&m.type==='league'?' Finestra di mercato: +500 crediti assegnati.':''}</div><div class="actions" style="justify-content:flex-end;margin-top:18px"><button class="btn primary" onclick="closeModal();view='home';render()">Continua →</button></div></div></div>`;state.match=null;save()}
