+function finishMatch(){const m=state.match;if(!m)return;if(m.mode==='detailed'&&m.minute<90){m.minute=90;renderMatchLive();return}let userGoals=m.events.filter(e=>e.goal&&e.player).length;let oppGoals=m.score[0]+m.score[1]-userGoals;if(userGoals+oppGoals===0)oppGoals=0;let summary=`${state.clubName} ${userGoals}–${oppGoals} ${m.opp}`;let user=state.table.find(t=>t.name===state.clubName),opp=state.table.find(t=>t.name===m.opp);if(m.type==='league'){recordResult(user,opp,m.home?userGoals:oppGoals,m.home?oppGoals:userGoals);simulateOtherGames();state.week++;advanceDate();}else{if(userGoals===oppGoals){if(Math.random()<.5)userGoals++;else oppGoals++}if(userGoals>oppGoals){state.cupRound++;if(state.cupRound>=5){state.trophies++;state.rep+=10;addNews(`${state.clubName} alza la Coppa nazionale! Trionfo storico per il club.`,`🏆`);}}else state.cupRound=5;summary=`${state.clubName} ${userGoals}–${oppGoals} ${m.opp} · Coppa`;}
