{standings.slice(-3).map((t,i)=>tableRow(t,standings.length-3+i)).join('')}</tbody></table><div class="actions" style="margin-top:14px"><button class="btn small" onclick="go('squad')">Gestisci la rosa</button><button class="btn small" onclick="go('world')">Apri Mondo Calcio</button><button class="btn small" onclick="openMatchSetup('cup')">Coppa nazionale</button></div></section><div class="grid" style="align-content:start"><section class="card section"><div class="section-title"><h2>Voce dalla clubhouse</h2><span class="tag">LIVE</span></div><div class="target"><strong>${esc(state.target)}</strong><span class="muted">La dirigenza valuta il tuo lavoro: <b class="${objectiveStatus().includes('Sotto')?'red':'lime'}">${objectiveStatus()}</b></span><div class="progress"><i style="width:${rank<=8?78:35}%"></i></div></div><div style="margin-top:16px" class="fixture"><div class="club"><div class="crest">${state.clubName.slice(0,2).toUpperCase()}</div><div><div class="opponent">${esc(state.clubName)}</div><small>Rosa · ${state.squad.length} giocatori</small></div></div><strong class="kick">${avgLevel()} OVR</strong></div><div class="fixture"><div class="club"><div class="crest">🏆</div><div><div class="opponent">Palmarès</div><small>Trofei in carriera</small></div></div><strong class="kick">${state.trophies}</strong></div></section><section class="card section"><div class="section-title"><h2>Ultime dal mondo</h2><button class="btn small" onclick="go('world')">Tutte →</button></div>${state.news.slice(0,2).map(feedItem).join('')||'<p class="muted">Le notizie arriveranno presto.</p>'}</section></div></div>`}
 function myRow(){return state.table.find(t=>t.name===state.clubName)}function tableRow(t,i){return `<tr class="${t.name===state.clubName?'mine':''}"><td class="rank">${i+1}</td><td style="text-align:left">${esc(t.name)}</td><td>${t.w+t.d+t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td></tr>`}function avgLevel(){return Math.round(state.squad.filter(p=>p.starter).reduce((a,p)=>a+p.overall,0)/Math.max(1,state.squad.filter(p=>p.starter).length))}function feedItem(n){return `<div class="feed-item"><div class="feed-icon">${n.icon}</div><div><p>${esc(n.text)}</p><small>${n.day||state.day} · ${n.kind==='social'?'Social':n.kind==='market'?'Mercato':'Mondo Calcio'}</small></div></div>`}
 function go(id){view=id;render()}

