### function scoreLive
function scoreLive(side){const m=state.match;const user= m.events.filter(e=>e.goal&&e.side==='user'&&e.min<=m.minute).length;const opp=m.events.filter(e=>e.goal&&e.side==='opp'&&e.min<=m.minute).length;return side===0?(m.home?user:opp):(m.home?opp:user)}

### function recordResult
function recordResult(a,b,homeGoals,awayGoals){if(!a||!b)return;a.gf+=homeGoals;a.ga+=awayGoals;b.gf+=awayGoals;b.ga+=homeGoals;if(homeGoals>awayGoals){a.w++;a.pts+=3;b.l++}else if(homeGoals<awayGoals){b.w++;b.pts+=3;a.l++}else{a.d++;b.d++;a.pts++;b.pts++}}

