    let userPens=3+Math.floor(Math.random()*4),oppPens=3+Math.floor(Math.random()*4);
    while(userPens===oppPens){if(Math.random()<.5)userPens++;else oppPens++}
    m.penalties=[userPens,oppPens];cupWinner=userPens>oppPens;
    penalties=` (rigori ${userPens}-${oppPens})`;
  }
  const won=m.type==='cup'&&cupWinner!==null?cupWinner:userGoals>oppGoals;
  const draw=m.type!=='cup'&&userGoals===oppGoals;
