  document.getElementById('modal-root').innerHTML=`<div class="modal-back"><div class="modal"><div class="eyebrow">FISCHIO FINALE · ${m.type==='cup'?'COPPA NAZIONALE':'CAMPIONATO'}</div><div class="scoreboard"><div class="team">${esc(m.home?state.clubName:m.opp)}</div><strong>${m.score[0]} – ${m.score[1]}</strong><div class="team">${esc(m.home?m.opp:state.clubName)}</div></div>${message}${penalties?`<div class="notice">Decisione ai rigori: ${m.penalties[0]}–${m.penalties[1]}.</div>`:''}<div class="notice" style="margin-top:14px">${won?'Ottimo lavoro, Mister.':draw?'Un punto importante per la classifica.':'La squadra dovrà reagire alla prossima.'} ${state.week%19===0&&m.type==='league'?' Finestra di mercato: +500 crediti assegnati.':''}</div><div class="actions" style="justify-content:flex-end;margin-top:18px"><button class="btn primary" onclick="closeModal();view='home';render()">Continua →</button></div></div></div>`;
